import fs from 'node:fs'
import path from 'node:path'

const root = process.cwd()
const states = {
  WHALE_GIRL_DATA_URL: 'whale-girl.png',
  WHALE_GIRL_CLOSED_DATA_URL: 'whale-girl-closed.png'
}

const lines = [
  '// Generated by scripts/generate-state-images.mjs. Do not edit by hand.'
]

for (const [name, filename] of Object.entries(states)) {
  const bytes = fs.readFileSync(path.join(root, 'assets', filename))
  lines.push(`export const ${name} = ${JSON.stringify(`data:image/png;base64,${bytes.toString('base64')}`)}`)
}

fs.writeFileSync(path.join(root, 'src/client/stateImageData.ts'), `${lines.join('\n')}\n`)
